def apply(rel, txt):
    import hashlib
    if rel != 'inc/designer.php':
        raise SystemExit('call_657: no hunk on ' + rel)
    for a, b in HUNKS:
        if txt.count(a) != 1:
            raise SystemExit('call_657: FATAL anchor x%d in %s: %r' % (txt.count(a), rel, a[:60]))
        txt = txt.replace(a, b)
    if hashlib.md5(txt.encode('utf-8')).hexdigest() != NEW_MD5:
        raise SystemExit('call_657: FATAL the file is not the reviewed text after the hunks')
    print('[hunk] %s: %d hunk(s), the result is the reviewed text' % (rel, len(HUNKS)))
    return txt


